<parameter=old_text>
package repair

func LastIndex(xs []int, target int) int {
	for i, v := range xs {
		if v == target {
			return i
		}
	}
	return -1
}
</parameter>
<parameter=new_text>
package repair

func LastIndex(xs []int, target int) int {
	for i := len(xs) - 1; i >= 0; i-- {
		if xs[i] == target {
			return i
		}
	}
	return -1
}
